const input = $input.first().json;
const mode = input.mode || 'inspire';

// Thèmes d'inspiration par pilier wellness
const inspirationThemes = {
  'pilates_mouvement': [
    'pilates studio aesthetic', 'reformer pilates workout', 'pilates body goals',
    'mat pilates exercises', 'pilates studio design minimal', 'barre workout aesthetic'
  ],
  'communaute_social': [
    'wellness community events', 'women empowerment gathering', 'social club aesthetic',
    'brunch aesthetic healthy', 'girl gang workout', 'fitness friends group'
  ],
  'wellness_selfcare': [
    'self care routine aesthetic', 'wellness morning routine', 'meditation space design',
    'healthy lifestyle flat lay', 'mindfulness journal aesthetic', 'holistic wellness'
  ],
  'evenements_lifestyle': [
    'wellness retreat aesthetic', 'yoga retreat design', 'popup event minimal',
    'lifestyle event branding', 'wellness workshop setup', 'boutique fitness event'
  ]
};

// Board IDs par catégorie (à configurer)
const boardMap = {
  'inspiration_pilates': '{{PINTEREST_BOARD_PILATES}}',
  'inspiration_wellness': '{{PINTEREST_BOARD_WELLNESS}}',
  'inspiration_events': '{{PINTEREST_BOARD_EVENTS}}',
  'inspiration_branding': '{{PINTEREST_BOARD_BRANDING}}',
  'publish_content': '{{PINTEREST_BOARD_PUBLISH}}'
};

if (mode === 'inspire') {
  const pillar = input.content_pillar || 'pilates_mouvement';
  const themes = inspirationThemes[pillar] || inspirationThemes['pilates_mouvement'];
  const randomTheme = themes[Math.floor(Math.random() * themes.length)];

  return [{
    json: {
      mode: 'inspire',
      search_query: input.custom_query || randomTheme,
      content_pillar: pillar,
      board_id: boardMap[`inspiration_${pillar.split('_')[0]}`] || boardMap['inspiration_wellness'],
      limit: input.limit || 25
    }
  }];
} else if (mode === 'publish') {
  return [{
    json: {
      mode: 'publish',
      board_id: input.board_id || boardMap['publish_content'],
      pin_title: input.pin_title,
      pin_description: input.pin_description,
      pin_link: input.pin_link || 'https://www.mouvementsocialclub.com',
      image_url: input.image_url,
      alt_text: input.alt_text || input.pin_title,
      content_type: input.content_type || 'pinterest_pin',
      schedule_date: input.schedule_date || null
    }
  }];
} else if (mode === 'moodboard') {
  return [{
    json: {
      mode: 'moodboard',
      board_id: input.board_id || boardMap[`inspiration_${input.content_pillar?.split('_')[0]}`],
      content_pillar: input.content_pillar
    }
  }];
}

return [{ json: { error: 'Mode non reconnu. Utiliser: inspire, publish, moodboard' } }];

